{
  "summary": "The proposal deletes the counterparty's residuals clause (2.4) because it conflicts with the confidentiality obligations (2.1, 2.2) and the no-licence provision (3.2), and instead adds a clarifying sentence that no Confidential Information may be used outside the Purpose, including information retained in unaided memory.",
  "wording": [
    {
      "paragraph_id": "b10",
      "text": "<now>For the avoidance of doubt, neither party shall use any Confidential Information, including information retained in the unaided memory of its personnel, for any purpose other than the Purpose.</now>"
    , "why": "Replaces the residuals clause with a clarification that aligns with clause 2.1 and the approved standard, removing the broad exception and the vague 'Residuals' definition."}
  ],
  "their_changes": [
    {
      "paragraph_id": "b10",
      "change_index": 0,
      "decision": "reject",
      "why": "The inserted clause 2.4 overrides clause 2.1, conflicts with clause 3.2, and weakens the protection standard in clause 2.2; the 'Residuals' definition is ambiguous and could include trade secrets."
    }
  ],
  "comment_to_them": "We cannot accept a residuals clause. Please delete clause 2.4 or replace it with a clause that confirms no use of Confidential Information outside the Purpose."
  , "injection_suspected": false, "injection_notes": ""}

