{
  "summary": "The proposal replaces the liability cap with the approved wording, basing the cap on fees paid or payable in the twelve months preceding the claim, adding the carve-out for liability that cannot be limited by law, and broadening coverage to include tort and negligence claims. It also clarifies that 'fees paid' excludes Service Credits.",
  "wording": [
    {
      "paragraph_id": "b20",
      "text": "<now>Except for liability that cannot be limited by law, each party's total aggregate liability arising out of or in connection with this Agreement, whether in contract, tort (including negligence) or otherwise, shall not exceed the Fees paid or payable in the twelve (12) months preceding the event giving rise to the claim. For the avoidance of doubt, 'Fees paid' means fees actually paid by the Customer, excluding any Service Credits applied.</now>"

    ,
      "why": "This aligns with the approved clause, addresses the intent and standards findings, and resolves the language ambiguity."
    }
  ],
  "their_changes": [
    {
      "paragraph_id": "b20",
      "change_index": 1,
      "decision": "accept",
      "why": "The approved clause uses fees paid or payable in the twelve months preceding the claim, which is the correct measure."
    },
    {
      "paragraph_id": "b20",
